```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <map>
#include <vector>
#include <algorithm>
using namespace std;

int main() {
    ifstream f1("produkty.txt");
    map<int, pair<string, int>> produkty;
    int id, cena;
    string nazwa;
    while (f1 >> id >> nazwa >> cena) {
        produkty[id] = {nazwa, cena};
    }
    ifstream f2("zamowienia.txt");
    int nrZam, idProd, ilosc;
    map<int, int> sumaIlosc;
    while (f2 >> nrZam >> idProd >> ilosc) {
        sumaIlosc[idProd] += ilosc;
    }
    vector<pair<int, string>> ranking;
    int total = 0;
    for (auto& s : sumaIlosc) {
        int przychod = produkty[s.first].second * s.second;
        ranking.push_back({przychod, produkty[s.first].first});
        total += przychod;
    }
    sort(ranking.begin(), ranking.end(), [](auto& a, auto& b) {
        if (a.first != b.first) return a.first > b.first;
        return a.second < b.second;
    });
    cout << "Przychod per produkt:" << endl;
    for (auto& r : ranking) {
        cout << "   " << r.second << ": " << r.first << endl;
    }
    cout << "Laczny przychod: " << total << endl;
    cout << "Produkt z najwyzszym przychodem: " << ranking[0].second << " (" << ranking[0].first << ")" << endl;
    return 0;
}
```

